function xls(name, head, rows) { const t = `<table><tr>${head.map(h => `<th>${esc(h)}</th>`).join('')}</tr>${rows.map(r => `<tr>${r.map(c => `<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</table>`, a = document.createElement('a'); a.href = URL.createObjectURL(new Blob(['\ufeff<html><meta charset="utf-8">' + t + '</html>'], { type: 'application/vnd.ms-excel' })); a.download = name + '.xls'; a.click(); }

