const ML = [['Budi Santoso', 8, 'Simulasi Dinamis Teorema Pythagoras', 'Matematika', 'buka media'], ['Felicia Tan', 8, 'Pengenalan Sintaks Python', 'Koding & KA', 'buka media'], ['Kenji Pratama', 7, 'Portal Beranda Siswa', '', 'buka laman'], ['Siti Rahma', 9, 'Lab Klasifikasi Citra & AI', 'Koding & KA', 'buka media'], ['Michael Wijaya', 8, 'Eksplorasi Ukuran Pemusatan Data', 'Matematika', 'buka media']].map((l, i) => ({ timestamp: new Date(Date.now() - (i * 7 + 3) * 60000).toISOString(), nama: l[0], kelas: l[1], nama_media: l[2], mapel: l[3], jenis: l[4] }));
