// ---- Kelola Media ----
const M = { q: '', k: '', m: '', s: '', sel: new Set(), p: 1 };
async function media(pg) {
  const j = await api('admin.media'); if (!j.success) return; const all = j.data.media; setPer(j.data.setting);
  const draw = () => {
    const f = all.filter(x => (!M.k || x.kelas == M.k) && (!M.m || x.mapel === M.m) && (!M.s || x.status === M.s) && (x.nama + x.topik).toLowerCase().includes(M.q.toLowerCase())), pages = Math.max(1, Math.ceil(f.length / 6)); M.p = Math.min(M.p, pages); const rows = f.slice((M.p - 1) * 6, M.p * 6);
    $('#mt').innerHTML = `${M.sel.size ? `<div class="bulk"><b>${M.sel.size}</b><div><b>media pembelajaran dipilih</b><br><small>Terapkan konfigurasi serentak untuk efisiensi semester</small></div><button data-b="Terbuka" class="bg">Ubah ke Terbuka</button><button data-b="Arsip (Hanya Admin)">Arsipkan (Hanya Admin)</button><button data-b="Nonaktif" class="br2">Hapus / Nonaktifkan</button><a href="#" id="bc">Batalkan Pilihan</a></div>` : ''}<div class="tw"><table class="mt"><tr><th><input type="checkbox" id="ca"></th><th>THUMBNAIL &amp; MEDIA</th><th>KELAS &amp; MAPEL</th><th>PLATFORM &amp; TAUTAN</th><th>PANDUAN LOGIN</th><th>STATUS AKSES</th><th></th></tr>${rows.map(m => { const n = steps(m.petunjuk).length, im = String(m.gambar || '').split(',')[0].trim(); return `<tr class="${m.status !== 'Terbuka' ? 'dim' : ''}"><td><input type="checkbox" data-s="${esc(m.id)}" ${M.sel.has(m.id) ? 'checked' : ''}></td><td><div class="mn"><span class="th" style="${im ? `background-image:url(${esc(im)})` : ''}">${im ? '' : '▭'}</span><div><b>${esc(m.nama)}</b><small>${esc(m.deskripsi).slice(0, 48)}…</small></div></div></td><td><span class="kb k${m.kelas}">Kelas ${m.kelas}</span><br><small>${esc(m.mapel)}</small></td><td>${esc(host(m.url))}<br><a class="lnk" href="${esc(m.url)}" target="_blank" rel="noopener">Uji Link ↗</a></td><td>${n ? `<span class="okk">✓ Lengkap (${n} langkah)</span>` : '<span class="muted">ⓘ Belum dikonfigurasi</span>'}<br><a class="lnk" href="#admin/media/edit/${esc(m.id)}">${n ? 'Lihat Panduan' : '+ Buat Panduan'}</a></td><td><select class="sp ${pill(m.status)}" data-st="${esc(m.id)}">${['Terbuka', 'Arsip (Hanya Admin)', 'Nonaktif'].map(s => `<option ${s === m.status ? 'selected' : ''}>${s}</option>`).join('')}</select></td><td><a class="chip" href="#admin/media/edit/${esc(m.id)}">Edit</a></td></tr>`; }).join('') || '<tr><td colspan="7" class="muted">Tidak ada media.</td></tr>'}</table></div><div class="pg"><span class="muted">Menampilkan ${f.length ? (M.p - 1) * 6 + 1 : 0} – ${Math.min(M.p * 6, f.length)} dari <b>${f.length}</b> media (Tahun Ajaran ${esc(SET.tahun_ajaran || '')} • Semester ${esc(SET.semester || '')})</span><div>${Array.from({ length: pages }, (_, i) => `<button class="pb ${i + 1 === M.p ? 'on' : ''}" data-p="${i + 1}">${i + 1}</button>`).join('')}</div></div>`;
    $('#ca').onchange = e => { rows.forEach(r => e.target.checked ? M.sel.add(r.id) : M.sel.delete(r.id)); draw(); };
    $$('[data-s]').forEach(c => c.onchange = () => { c.checked ? M.sel.add(c.dataset.s) : M.sel.delete(c.dataset.s); draw(); }); $$('[data-p]').forEach(b => b.onclick = () => { M.p = +b.dataset.p; draw(); });
    $$('[data-st]').forEach(s => s.onchange = async () => { const r = await api('admin.mediaStatus', { id: s.dataset.st, status: s.value }); all.find(x => x.id === s.dataset.st).status = s.value; s.className = 'sp ' + pill(s.value); C.toast(r.success ? 'Status diubah' : r.message); });
    $$('[data-b]').forEach(b => b.onclick = async () => { const r = await api('admin.mediaBulk', { ids: [...M.sel], status: b.dataset.b }); all.forEach(x => M.sel.has(x.id) && (x.status = b.dataset.b)); M.sel.clear(); C.toast(r.success ? 'Diterapkan' : r.message); draw(); }); $('#bc') && ($('#bc').onclick = e => { e.preventDefault(); M.sel.clear(); draw(); });
  };
  const c = k => all.filter(k).length;
  pg.innerHTML = head('SMP MAITREYAWIRA BINTAN CENTER • PORTAL KURIKULUM', 'Kelola Media Pembelajaran Interaktif', 'Daftar semua media simulasi Matematika dan modul Koding &amp; KA. Tambah, edit panduan login, urutkan, dan tentukan status akses siswa.', `<a class="btn soft" href="#admin/siswa">▦ Impor Spreadsheet</a><a class="btn" href="#admin/media/edit/new">${ic('plus')} Tambah Media Baru</a>`) +
    `<div class="g4">${stat('s-w', 'TOTAL MEDIA AKTIF', all.length, '', '', 'book')}${stat('s-w', 'STATUS TERBUKA SISWA', c(x => x.status === 'Terbuka'), '', '', 'chart')}${stat('s-w', 'ARSIP GURU', c(x => x.status.indexOf('Arsip') === 0), '', '', 'book')}${stat('s-w', 'PANDUAN LOGIN SIAP', Math.round(c(x => steps(x.petunjuk).length) / (all.length || 1) * 100), '%', '', 'chart')}</div>
<div class="fb"><input id="fq" placeholder="🔎 Cari nama media, materi, atau topik…" value="${esc(M.q)}"><select id="fk"><option value="">Semua Kelas (7, 8, 9)</option><option>7</option><option>8</option><option>9</option></select><select id="fm"><option value="">Semua Mapel</option><option>Matematika</option><option>Koding &amp; KA</option></select><select id="fs"><option value="">Semua Status</option><option>Terbuka</option><option>Arsip (Hanya Admin)</option><option>Nonaktif</option></select><a href="#" id="fr">↻ Reset</a></div><div id="mt"></div><div class="tip">💡 <div><b>Tips Guru &amp; Tim TIK</b><br>Gunakan status <b>"Arsip (Hanya Admin)"</b> untuk materi yang sedang dipersiapkan atau materi semester lalu yang ingin disembunyikan dari siswa tanpa menghapus data log evaluasi dan catatan analitika.</div></div>`;
  $('#fk').value = M.k; $('#fm').value = M.m; $('#fs').value = M.s;
  $('#fq').oninput = e => { M.q = e.target.value; M.p = 1; draw(); }; $('#fk').onchange = e => { M.k = e.target.value; M.p = 1; draw(); }; $('#fm').onchange = e => { M.m = e.target.value; M.p = 1; draw(); }; $('#fs').onchange = e => { M.s = e.target.value; M.p = 1; draw(); };
  $('#fr').onclick = e => { e.preventDefault(); Object.assign(M, { q: '', k: '', m: '', s: '', p: 1 }); media(pg); }; countUp(pg); draw();
}

