  pg.innerHTML = head('PORTAL ADMIN › LOG AKTIVITAS', 'Riwayat Log Aktivitas &amp; Audit Akses Siswa', 'Catatan terpusat waktu nyata setiap siswa membuka portal dan meluncurkan media pembelajaran interaktif.', `<span class="pill-g">● Batch 10 log / tulis</span><button class="btn soft" id="rf">⟳ Segarkan</button><button class="btn" id="xl">${ic('down')} Unduh Rekap</button><button class="btn ghost" id="pd">Cetak PDF</button>`) +
    `<div class="g4">${stat('s-w', 'TOTAL SESI HARI INI', td.length, ' Aktivitas', '', 'chart')}${stat('s-w', 'SISWA AKTIF HARI INI', new Set(td.map(l => l.nama)).size, ' Siswa', '', 'users')}<div class="st s-w"><div class="sl"><span>MEDIA PALING SERING DIBUKA</span></div><div class="sn sm">${esc(topm ? topm[0] : '-')}</div><small>${topm ? topm[1] + '× peluncuran media' : ''}</small></div><div class="st s-w"><div class="sl"><span>STATUS KUOTA BATCH GAS</span></div><div class="sn sm okk">● Optimal</div><small>Log ditulis per 10 entri / 5 menit</small></div></div>
<div class="fb"><input id="lq" placeholder="🔎 Cari Nama Siswa atau Media…"><select id="lk"><option value="">Semua Kelas</option><option>7</option><option>8</option><option>9</option></select><select id="lj"><option value="">Semua Aktivitas</option><option>buka media</option><option>buka laman</option></select></div><div class="panel printable"><h3>Catatan Log Real-Time <span class="tag">Terupdate Waktu Nyata</span></h3><div id="lt"></div></div><div class="tip">🛡 <div><b>Arsitektur Anti-Quota Exceeded:</b> data log dikonsolidasi per <b>10 transaksi atau interval 5 menit</b> ke tab <code>Log_Aktivitas</code> Google Sheets untuk melindungi kuota eksekusi Apps Script.</div></div>`;
  $('#lq').oninput = e => { LG.q = e.target.value; LG.p = 1; draw(); }; $('#lk').onchange = e => { LG.k = e.target.value; LG.p = 1; draw(); }; $('#lj').onchange = e => { LG.j = e.target.value; LG.p = 1; draw(); }; $('#rf').onclick = () => logs(pg); $('#pd').onclick = () => print();
